.circuit-active-root .circuit-continuation-inquiry-steps {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14em), 1fr));
    gap: 12px;
    min-width: 0;
    margin: 16px 0 0;
    padding: 0;
    list-style: none;
}
.circuit-active-root .circuit-continuation-inquiry-step {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    min-width: 0;
    padding: 13px;
    border: 1px solid #608d80;
    border-radius: 10px;
    background: #0d292b;
}
.circuit-active-root .circuit-continuation-inquiry-number {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    min-width: 26px;
    min-height: 26px;
    border: 1px solid #7dbca5;
    border-radius: 50%;
    color: #e0f5ea;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.6;
}
.circuit-active-root .circuit-continuation-inquiry-copy {
    min-width: 0;
}
.circuit-active-root strong.circuit-continuation-inquiry-heading {
    display: block;
    color: #edf8f2;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.6;
    overflow-wrap: anywhere;
}
.circuit-active-root p.circuit-continuation-inquiry-prompt {
    margin: 5px 0 0;
    color: #c5dfd5;
    font-size: 13px;
    line-height: 1.7;
    overflow-wrap: anywhere;
}
.circuit-active-root .circuit-continuation-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    min-width: 0;
}
@media (forced-colors: active) {
    .circuit-active-root .circuit-continuation-inquiry-step,
    .circuit-active-root .circuit-continuation-inquiry-number {
        border-color: CanvasText;
        background: Canvas;
        color: CanvasText;
    }
    .circuit-active-root strong.circuit-continuation-inquiry-heading,
    .circuit-active-root p.circuit-continuation-inquiry-prompt {
        color: CanvasText;
    }
}
